const scene=document.querySelector('.cover-scene');const machine=document.querySelector('.cover-machine');const statusLabel=document.querySelector('.print-status');const paperIntro=document.querySelector('#paper-intro');const openingVideo=document.querySelector('#opening-video');const reduceMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;let timers=[];let printing=false;let revealing=false;
function later(fn,ms){timers.push(setTimeout(fn,reduceMotion?0:ms))}
function printReceipt(){if(printing)return;printing=true;scene.classList.remove('previews-ready','is-feeding');machine.classList.remove('printed');void scene.offsetWidth;statusLabel.textContent='机器启动中…';document.querySelector('#cover-print').disabled=true;
later(()=>{statusLabel.textContent='正在打印目录…';scene.classList.add('is-feeding')},900);
later(()=>{scene.classList.add('previews-ready')},5500);
later(()=>{scene.classList.remove('is-feeding');machine.classList.add('printed');statusLabel.textContent='目录打印完成';printing=false;document.querySelector('#cover-print').disabled=false},6500)}
function enterCover(){timers.forEach(clearTimeout);timers=[];printing=false;scene.classList.remove('arriving','machine-ready','previews-ready','is-feeding');machine.classList.remove('printed');void scene.offsetWidth;scene.classList.add('arriving');statusLabel.textContent='等待机器就绪';later(()=>scene.classList.add('machine-ready'),1300);later(printReceipt,3000)}
document.querySelector('#cover-replay').onclick=enterCover;document.querySelector('#cover-print').onclick=printReceipt;
document.querySelectorAll('.cover-word').forEach(word=>{word.onclick=()=>{word.classList.remove('word-bounce');void word.offsetWidth;word.classList.add('word-bounce');const burst=document.querySelector('.cover-burst');burst.classList.remove('burst-react');void burst.offsetWidth;burst.classList.add('burst-react')};word.addEventListener('animationend',()=>word.classList.remove('word-bounce'))});
document.querySelectorAll('[data-cover-project]').forEach(link=>link.onclick=e=>{e.preventDefault();showProject(Number(link.dataset.coverProject))});
function showCover(){if(revealing)return;revealing=true;document.body.style.overflow='';paperIntro.classList.add('video-leaving');enterCover();setTimeout(()=>{paperIntro.hidden=true;openingVideo.pause()},700)}
function playOpening(){paperIntro.classList.add('playing');openingVideo.play().catch(()=>{paperIntro.classList.remove('playing')})}
openingVideo.addEventListener('ended',showCover);document.body.style.overflow='hidden';document.querySelector('#paper-open').onclick=playOpening;document.querySelector('#paper-skip').onclick=showCover;
document.querySelectorAll('[data-receipt-project]').forEach(link=>{link.onclick=e=>{e.preventDefault();showProject(Number(link.dataset.receiptProject))};const stamp=document.querySelector(`[data-cover-project="${link.dataset.receiptProject}"]`);link.onmouseenter=()=>stamp?.classList.add('linked');link.onmouseleave=()=>stamp?.classList.remove('linked')});
